 1→/**
 2→ * Generate a UUID v4 string.
 3→ * Uses crypto.randomUUID() in secure contexts (HTTPS / localhost),
 4→ * falls back to crypto.getRandomValues() for insecure contexts (e.g. HTTP over LAN).
 5→ */
 6→export function generateUUID(): string {
 7→  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
 8→    return crypto.randomUUID();
 9→  }
10→  return '10000000-1000-4000-8000-100000000000'.replace(/[018]/g, (c) => {
11→    const n = Number(c);
12→    return (n ^ (crypto.getRandomValues(new Uint8Array(1))[0] & (15 >> (n / 4)))).toString(16);
13→  });
14→}
