import ast
import sys
import os

project_root = "/Users/cyyeh/Desktop/duckdb-data-agent"

# Collect all project Python files (excluding .venv)
py_files = []
for root, dirs, files in os.walk(os.path.join(project_root, "backend")):
    # Skip .venv
    if ".venv" in root:
        continue
    for f in files:
        if f.endswith(".py"):
            py_files.append(os.path.join(root, f))

def get_unused_imports(filepath):
    """Analyze a Python file for unused imports using AST."""
    with open(filepath, 'r') as f:
        try:
            source = f.read()
            tree = ast.parse(source, filename=filepath)
        except SyntaxError:
            return []

    # Collect imports
    imports = {}  # name -> (line_number, import_text)

    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                name = alias.asname if alias.asname else alias.name
                # For dotted imports like "import os.path", the bound name is "os"
                bound_name = name.split('.')[0]
                import_text = f"import {alias.name}" + (f" as {alias.asname}" if alias.asname else "")
                imports[bound_name] = (node.lineno, import_text)
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ''
            for alias in node.names:
                if alias.name == '*':
                    continue  # Skip star imports
                name = alias.asname if alias.asname else alias.name
                import_text = f"from {module} import {alias.name}" + (f" as {alias.asname}" if alias.asname else "")
                imports[name] = (node.lineno, import_text)

    # Collect all name usages (excluding the import statements themselves)
    used_names = set()

    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            # Check if this Name node is part of an import statement
            used_names.add(node.id)
        elif isinstance(node, ast.Attribute):
            # For things like module.func, we need the module name
            if isinstance(node.value, ast.Name):
                used_names.add(node.value.id)
        elif isinstance(node, ast.FunctionDef) or isinstance(node, ast.AsyncFunctionDef):
            used_names.add(node.name)
            for decorator in node.decorator_list:
                if isinstance(decorator, ast.Name):
                    used_names.add(decorator.id)
                elif isinstance(decorator, ast.Attribute) and isinstance(decorator.value, ast.Name):
                    used_names.add(decorator.value.id)
        elif isinstance(node, ast.ClassDef):
            used_names.add(node.name)
            for base in node.bases:
                if isinstance(base, ast.Name):
                    used_names.add(base.id)
        # Handle string annotations (type hints as strings)
        elif isinstance(node, ast.Constant) and isinstance(node.value, str):
            # Could be a type annotation string - add words that look like identifiers
            for word in node.value.split():
                word = word.strip("[](),|")
                if word.isidentifier():
                    used_names.add(word)

    # Also scan for names used in decorators and other contexts
    # by doing a simpler text search for edge cases
    source_lines = source.split('\n')

    unused = []
    for name, (lineno, import_text) in imports.items():
        if name not in used_names:
            # Double check: do a text search to handle edge cases
            # (string references, __all__ exports, etc.)
            name_found_in_source = False
            for i, line in enumerate(source_lines):
                if i + 1 == lineno:
                    continue  # Skip the import line itself
                if name in line:
                    name_found_in_source = True
                    break
            if not name_found_in_source:
                unused.append((lineno, import_text, name))

    return unused

results = []
for filepath in sorted(py_files):
    unused = get_unused_imports(filepath)
    if unused:
        rel_path = os.path.relpath(filepath, project_root)
        for lineno, import_text, name in sorted(unused):
            results.append(f"{filepath}:{lineno}: '{name}' imported but unused ({import_text})")

if results:
    for r in results:
        print(r)
else:
    print("No unused imports found.")
PYEOF

